import { THEME_COLOR_SCHEMES, THEME_MODES, type ThemeMode } from "./theme";

export type TokenFamily =
  | "colour"
  | "spacing"
  | "radius"
  | "type"
  | "elevation"
  | "focus"
  | "font";

/** One design token: a runtime CSS variable with a value in every theme mode. */
export type Token = Readonly<{
  family: TokenFamily;
  name: string;
  cssVar: `--${string}`;
  utility: string;
  values: Readonly<Record<ThemeMode, string>>;
  note?: string;
}>;

const CSS_HEADER =
  "/* Generated by scripts/build-v1-tokens.mjs from src/v1/styles/tokens.json. Do not edit. */";

const TABLE_HEADER =
  "| Family | Token | CSS variable | Utility | Light | Dark | Unstract |";
const TABLE_SEPARATOR = "| --- | --- | --- | --- | --- | --- | --- |";

export function sameInEveryMode(
  value: string,
): Readonly<Record<ThemeMode, string>> {
  return { light: value, dark: value, unstract: value };
}

/**
 * One `.v1[data-theme=…]` block per mode: the mode's `color-scheme` (so native
 * controls, scrollbars and autofill follow data-theme, not the OS), then every
 * token in source order.
 */
export function renderTokensCss(tokens: readonly Token[]): string {
  const blocks = THEME_MODES.map((mode) => {
    const declarations = tokens.map(
      (token) => `  ${token.cssVar}: ${token.values[mode]};\n`,
    );
    const scheme = `  color-scheme: ${THEME_COLOR_SCHEMES[mode]};\n`;
    return `.v1[data-theme="${mode}"] {\n${scheme}${declarations.join("")}}\n`;
  });
  return `${CSS_HEADER}\n${blocks.join("")}`;
}

/** Markdown table of every token, one row each, for the gallery and the dev-spec snapshot. */
export function renderTokenTable(tokens: readonly Token[]): string {
  const rows = tokens.map((token) => {
    const cells = [
      token.family,
      token.name,
      `\`${token.cssVar}\``,
      `\`${token.utility}\``,
      ...THEME_MODES.map((mode) => token.values[mode]),
    ];
    return `| ${cells.join(" | ")} |\n`;
  });
  return `${TABLE_HEADER}\n${TABLE_SEPARATOR}\n${rows.join("")}`;
}
